<?php declare(strict_types=1); $money=static fn($c):string=>($filters['currency']==='BRL'?'R$':$filters['currency']).' '.number_format(((int)$c)/100,2,',','.'); ob_start(); ?>
<section class="admin-page-head"><div><p class="admin-eyebrow">Dados financeiros</p><h2>Financeiro</h2><p>Recebimentos menos estornos confirmados. Créditos operacionais não são receita.</p></div></section>
