<label>Gateway<select name="gateway"><option value="">Todos</option><?php foreach(['stripe','pagarme'] as $v): ?><option value="<?= $v ?>"<?= $filters['gateway']===$v?' selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></label>
<label>Status<select name="status"><option value="">Todos</option><?php foreach(['paid'=>'Pago','pending'=>'Pendente','failed'=>'Recusado','canceled'=>'Cancelado','refunded'=>'Estornado'] as $key=>$label): ?><option value="<?= $key ?>"<?= $filters['status']===$key?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label>
<label>Usuário<input name="user" inputmode="numeric" value="<?= e($filters['user']) ?>"></label><label>Plano<input name="plan" inputmode="numeric" value="<?= e($filters['plan']) ?>"></label>
<label>De (UTC)<input type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>Até (UTC)<input type="date" name="to" value="<?= e($filters['to']) ?>"></label><button class="admin-button">Filtrar</button></form></section>
